import{_ as n,C as a,o as i,c as r,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Deferred Agent Environments Need Stable Identity, Not Replacement-Based Provisioning","description":"","frontmatter":{"title":"Deferred Agent Environments Need Stable Identity, Not Replacement-Based Provisioning","date":"2026-08-07","column":"open-source-engineering","category":"daily","summary":"Deferred environments should converge report-first and materialize-first flows on one stable logical identity with explicit Pending, Ready, and Failed states. Local idempotence reduces ambiguity but does not prove restart durability or distributed exactly-once provisioning.","item_id":"Q-20260807-03","source_research_object":"research/analysis/Q-20260807-03-stable-identity-provisioning-gate.md","source_reading_result":"research/reading/Q-20260807-03-deferred-environment-provisioning.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-07-stable-identity-provisioning-gate-cover-v2.jpg"},"headers":[],"relativePath":"en/engineering/2026-08-07-stable-identity-provisioning-gate.md","filePath":"en/engineering/2026-08-07-stable-identity-provisioning-gate.md","lastUpdated":1787407830000}'),d={name:"en/engineering/2026-08-07-stable-identity-provisioning-gate.md"};function l(c,e,p,u,h,m){const t=a("ArticleCover");return i(),r("div",null,[o(t,{image:"/assets/covers/daily-2026-08-07-stable-identity-provisioning-gate-cover-v2.jpg",kicker:"Open-source Engineering · Daily Research",title:"Deferred Agent Environments Need Stable Identity, Not Replacement-Based Provisioning",summary:"Deferred environments should converge report-first and materialize-first flows on one stable logical identity with explicit Pending, Ready, and Failed states. Local idempotence reduces ambiguity but does not prove restart durability or distributed exactly-once provisioning.",version:"Q-20260807-03",status:"Daily Runtime V5 · 2026-08-07",languageHref:"/zh/engineering/2026-08-07-stable-identity-provisioning-gate",languageLabel:"中文"}),e[0]||(e[0]=s(' # Deferred Agent Environments Need Stable Identity, Not Replacement-Based Provisioning <p>Agent runtimes increasingly depend on resources that must be referenced before they are usable: remote sandboxes, browser environments, workspaces, or tool containers may exist logically while still Pending and become Ready or Failed later.</p><p>The dangerous API pattern is not simply “slow provisioning.” It is replacing the resource object every time lifecycle state changes. Once identity drifts, queued tasks, UI projections, references, and audit records must chase a new object, increasing race and reconciliation risk.</p><p>The same-day Research Object points to a cleaner pattern: stable identity plus an explicit report-and-materialize lifecycle.</p><h2 id="central-judgment" tabindex="-1">Central judgment <a class="header-anchor" href="#central-judgment" aria-label="Permalink to &quot;Central judgment&quot;">​</a></h2><p><strong>Provisioning state should change; resource identity should not.</strong></p><p>Pending, Ready, and Failed are lifecycle classes of one logical resource. A <code>report</code> operation submits status. A <code>materialize</code> operation establishes or returns the provisioned lifecycle object. Report-first and materialize-first flows should converge on the same identity rather than using replacement/upsert semantics to overwrite earlier objects.</p><p>This local idempotence is useful, but its boundary matters: a lock-protected in-process manager does not establish crash durability, multi-process consensus, or exactly-once external provisioning.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>This candidate consumes only the Production-authorized <code>Q-20260807-03</code> Research Object. Production did not return to the Signal Pool or Reading Result for new research and did not add new external facts. The Reading Result is retained only as the evidence boundary and provenance path declared by the Research Object.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The Research Object preserves five mechanisms.</p><p>First, deferred-environment state is consolidated around two manager-level operations: provisioning-status reporting and explicit materialization. Callers no longer need multiple independent upsert paths to express the same lifecycle.</p><p>Second, report-first and materialize-first behavior converges on one stable provisioned environment identity. Pending, Ready, or Failed updates do not force queued tasks to follow a replacement object.</p><p>Third, ordinary environments and provisioned environments are structurally distinct. A provisioning report to an ordinary environment is ignored as <code>Ok(None)</code>, while materialization against an ordinary environment returns a typed <code>ProvisioningModeConflict</code> and preserves the existing object. That asymmetry may be intentional, but without an audit surface <code>Ok(None)</code> can look like an accepted state transition to the caller.</p><p>Fourth, terminal lifecycle class is sticky. Ready cannot flip to Failed and Failed cannot flip to Ready, while matching terminal reports may repeat idempotently. However, Ready payload details remain mutable within the Ready class, so “idempotent Ready” is not equivalent to a completely immutable terminal record.</p><p>Fifth, removing a registration-handle Drop behavior eliminates an implicit abandonment-to-failure transition. That makes lifecycle ownership more explicit, but it also removes one automatic signal that provisioning work disappeared. Timeout and terminal-failure ownership must move to a named higher-level component.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Design</th><th>Identity</th><th>Lifecycle update</th><th>Conflict behavior</th><th>Recovery boundary</th></tr></thead><tbody><tr><td>Replacement / upsert</td><td>State change may replace the object</td><td>Distributed across callers</td><td>Semantics can be overwritten</td><td>Tasks and references chase new objects</td></tr><tr><td>Stable identity + report/materialize</td><td>One logical resource ID</td><td>Explicit Pending / Ready / Failed reports</td><td>Typed mode conflict; some reports may be ignored</td><td>Better in-process race and order behavior</td></tr><tr><td>Durable production extension</td><td>Stable resource ID + persistent event/receipt</td><td>Local state plus durable transition record</td><td>Conflicts and ignored reports are auditable</td><td>Restart reconciliation is possible but external effects still need idempotency</td></tr></tbody></table><p>The first two rows summarize the Research Object. The third is a Research Center production-runtime extension, not a capability established by the analyzed implementation.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>The reusable architecture is to separate four concepts: <strong>resource identity, lifecycle class, readiness payload, and connection/use activation.</strong></p><p>Identity should stay stable because tasks and UI surfaces need a durable reference. Lifecycle class should be explicit because Pending, Ready, and Failed have different control meaning. Readiness payload may be versioned because endpoints, capability roots, or metadata can still be refined. Connection/use should be modeled separately again, because “the environment is Ready” does not mean “a task has connected and started using it.”</p><p>Order independence also matters. A status report may arrive before an explicit Pending object. If both operations eventually converge on the same identity, callers do not have to manufacture correctness through retry order.</p><p>But local idempotence cannot substitute for distributed durability. After a process restart, without a durable event, effect receipt, or external idempotency key, the runtime may not know whether a provisioning side effect already happened. Re-materializing can therefore create a second real resource even if the in-memory manager had perfect idempotence before the crash.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>For Digital Employees, remote browser, sandbox, workspace, and tool environments should have durable logical resource IDs. Provisioning completion and connection/use start should be separate observable transitions so Ready does not silently imply Active.</p><p>A named runtime owner must control timeout and abandonment. Once Drop no longer turns a disappeared registration into Failed, the owner needs to detect an orphaned Pending state and emit an explicit terminal verdict.</p><p>For CodeFlowMu, worker/tool-environment provisioning should converge on report-and-materialize operations rather than caller-specific replacement/upsert APIs. A durable FCoP/Runtime layer above the manager can record append-only provisioning events, effect receipts, and recovery reconciliation. Ignored reports to ordinary environments should also create a diagnostic when operator comprehension or auditability matters, allowing the system to distinguish a benign late report from a caller bug.</p><h2 id="boundaries-and-counter-evidence" tabindex="-1">Boundaries and counter-evidence <a class="header-anchor" href="#boundaries-and-counter-evidence" aria-label="Permalink to &quot;Boundaries and counter-evidence&quot;">​</a></h2><p>The evidence establishes local manager semantics and regression coverage. It does not demonstrate restart recovery, multi-process races, successful remote connection, fleet-level reliability, or exactly-once external effects.</p><p><code>Ok(None)</code> may hide a caller error. Removing Drop-based failure can leave Pending unowned if no timeout controller exists. Ready payload remains mutable within the Ready class. Backward compatibility for downstream users of removed APIs is also not established by this Research Object.</p><p>The defensible conclusion is therefore narrower: stable identity and explicit lifecycle admission reduce local ambiguity. They do not prove that distributed provisioning is solved.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>Four questions remain: which component owns timeout and terminal failure; whether ignored reports should always emit an audit event and at what severity; what durable event/receipt layer can recover Pending/Ready/Failed after restart without duplicating external effects; and which Ready payload fields should become frozen or versioned at which lifecycle point.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The visual centers one Stable Resource ID, shows report-first and materialize-first flows converging on Pending/Ready/Failed, and separates Connection/Use from provisioning truth. A lower durable event/receipt layer is explicitly labeled as a production extension rather than a capability proven by the source.</p><h2 id="evidence-and-references" tabindex="-1">Evidence and references <a class="header-anchor" href="#evidence-and-references" aria-label="Permalink to &quot;Evidence and references&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260807-03-stable-identity-provisioning-gate.md" target="_blank" rel="noreferrer">Research Object — Stable-Identity Provisioning Gate</a>: the sole analytical input, including lifecycle semantics, uncertainty, counter-evidence, and engineering impact.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260807-03-deferred-environment-provisioning.md" target="_blank" rel="noreferrer">Reading Result — Deferred environment provisioning</a>: the evidence boundary and provenance record declared by the Research Object; Production did not re-analyze this file.</li></ol>',39))])}const y=n(d,[["render",l]]);export{g as __pageData,y as default};
